CREATE OR REPLACE FUNCTION public.icash_prepare_sms_inbound_reply(p_account uuid, p_thread uuid, p_reply uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;m public.icash_text_messages;question public.icash_text_messages;opening public.icash_sms_seller_openings;outgoing uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 if exists(select 1 from public.icash_text_threads candidate_thread join public.icash_deal_files candidate_deal on candidate_deal.id=candidate_thread.deal_id and candidate_deal.account_id=candidate_thread.account_id where candidate_thread.id=p_thread and candidate_thread.account_id=p_account and public.icash_seller_limited_contact(p_account,candidate_deal.screening_id)) then
  return public.icash_prepare_limited_seller_text(p_account,p_thread,p_reply);
 end if;
 select * into opening from public.icash_sms_seller_openings where thread_id=p_thread and account_id=p_account;
 if not found then return public.icash_prepare_sms_reply_before_owner_question(p_account,p_thread,p_reply);end if;
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account for update;
 select * into opening from public.icash_sms_seller_openings where thread_id=t.id and account_id=p_account for update;
 if opening.owner_reply_id=p_reply then return null;end if;
 if opening.interest_message_id is not null then return public.icash_prepare_sms_reply_before_owner_question(p_account,p_thread,p_reply);end if;
 if not public.icash_outreach_sms_current(p_account) or t.party<>'seller' or t.paused or t.ai_mode<>'auto'
  or not public.icash_sms_thread_review_current(p_account,t.id,false)
  or exists(select 1 from public.icash_text_suppressions where phone=t.recipient)
  or not exists(select 1 from public.icash_accounts where id=p_account and not bot_paused) then return null;end if;
 select * into m from public.icash_text_messages where id=p_reply and thread_id=t.id and account_id=p_account and direction='incoming' and state='received';
 if not found then return null;end if;
 select * into question from public.icash_text_messages where id=opening.owner_question_id and account_id=p_account and thread_id=t.id and direction='outgoing' and state in ('accepted','delivered') and provider_id is not null;
 if exists(select 1 from public.icash_seller_progress_settings where enabled and dialogue_enabled) then
  select sent.* into question from public.icash_text_messages sent join public.icash_text_ai_jobs j on j.outgoing_id=sent.id and j.account_id=sent.account_id and j.thread_id=sent.thread_id
   where sent.account_id=p_account and sent.thread_id=t.id and sent.direction='outgoing' and sent.state='delivered' and sent.provider_id is not null and sent.created_at<m.created_at
    and j.analysis->>'dialoguePolicy'='seller-dialogue-v1' and j.analysis->>'dialogueAction'='clarify_ownership'
   order by sent.created_at desc,sent.id desc limit 1;
  if not found then select * into question from public.icash_text_messages where id=opening.owner_question_id and account_id=p_account and thread_id=t.id and direction='outgoing' and state in ('accepted','delivered') and provider_id is not null;end if;
 end if;
 -- Whole-message answers only. A bare interested reply is not ownership confirmation.
 if question.id is null or m.created_at<question.created_at
  or lower(trim(m.body)) !~ '^(yes|yeah|yep|yes i am|i am|i am the owner|i''m the owner|yes i am the owner|yes that is me|yes that''s me)[.! ,]*$'
  or exists(select 1 from public.icash_text_messages x where x.thread_id=t.id and x.account_id=p_account and x.id not in (m.id,question.id) and x.created_at>=question.created_at) then return null;end if;
 outgoing:=public.icash_queue_text(p_account,t.id,m.id,case when t.seller_intake_id is not null then 'Would you consider a cash offer?' else 'Would you be interested in selling your property for all cash?' end,'{}');
 update public.icash_sms_seller_openings set owner_reply_id=m.id,interest_message_id=outgoing where thread_id=t.id and account_id=p_account;
 return outgoing;
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_sms_reply_before_owner_question(p_account uuid, p_thread uuid, p_reply uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;m public.icash_text_messages;opener public.icash_text_messages;d public.icash_deal_files;r public.icash_inbound_voice_routes;outgoing uuid;expiry timestamptz;body text;positive boolean;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 if not public.icash_sms_inbound_campaign_current(p_account) then return null;end if;
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account for update;
 if not found or t.party<>'seller' or t.paused or t.ai_mode<>'auto' then return null;end if;
 select * into m from public.icash_text_messages where id=p_reply and thread_id=t.id and account_id=p_account and direction='incoming' and state='received';if not found then return null;end if;
 if exists(select 1 from public.icash_text_suppressions where phone=t.recipient) then return null;end if;
 if exists(select 1 from public.icash_sms_inbound_invitations where thread_id=t.id) then return null;end if;
 select msg.* into opener from public.icash_seller_opener_assignments a
 left join public.icash_sms_seller_openings opening on opening.thread_id=a.thread_id and opening.account_id=a.account_id
 join public.icash_text_messages msg on msg.id=case when opening.thread_id is null then a.message_id else opening.interest_message_id end and msg.account_id=a.account_id and msg.thread_id=a.thread_id
 where a.thread_id=t.id and a.account_id=p_account and msg.state in ('accepted','delivered') and msg.provider_id is not null and not a.opted_out;
 positive:=lower(trim(m.body)) ~ '^(yes|yeah|yep|sure|yes please|i am interested|i''m interested|interested|yes i am interested|yes i''m interested)[.! ]*$';
 if opener.id is null or m.created_at<opener.created_at or exists(select 1 from public.icash_text_messages x where x.thread_id=t.id and x.id not in (m.id,opener.id) and x.created_at>opener.created_at) then positive:=false;end if;
 if not positive then
 insert into public.icash_text_ai_jobs(account_id,thread_id,message_id,state,analysis) values(p_account,t.id,m.id,'needs_review',jsonb_build_object('summary','SMS-first campaign: no unambiguous positive response to the recorded opener. No invitation sent.','action','review','sourceMessageId',m.id)) on conflict(message_id) do nothing;
 return null;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account and stage not in ('closed','cancelled') and coalesce(terms->>'practice','false')<>'true';if not found or d.screening_id is null then return null;end if;
 -- A shared sender must map to exactly one reviewed inbound number.
 if (select count(*) from public.icash_inbound_voice_routes where business_number=t.sender and enabled and reviewed_until>now() and agent_config_hash is not null)<>1 then return null;end if;
 select * into r from public.icash_inbound_voice_routes where business_number=t.sender and enabled and reviewed_until>now() and agent_config_hash is not null;
 if not exists(select 1 from public.icash_accounts where id=p_account and not bot_paused) or not exists(select 1 from public.icash_customer_identities where account_id=p_account and length(trim(principal))>0) then return null;end if;
 if not public.icash_sms_thread_review_current(p_account,t.id,false) then return null;end if;
 expiry:=least(public.icash_sms_thread_dispatch_until(p_account,t.id),r.reviewed_until,now()+interval '7 days');
 body:='Call '||substring(r.called_number from 2)||' to discuss a possible cash offer for your property with our AI assistant.';
 outgoing:=public.icash_queue_text(p_account,t.id,m.id,body,'{}');
 insert into public.icash_sms_inbound_invitations(account_id,thread_id,deal_id,screening_id,opener_id,reply_id,message_id,called_number,sender,recipient,expires_at) values(p_account,t.id,d.id,d.screening_id,opener.id,m.id,outgoing,r.called_number,t.sender,t.recipient,expiry);
 return outgoing;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_dialogue_context(p_account uuid, p_message uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_text_messages;t public.icash_text_threads;x public.icash_text_messages;
 prior public.icash_text_messages;prior_action text;prior_anchor text;b text;source_at numeric;
 condition_state text;condition_id uuid;condition_quote text;condition_answer uuid;
 action text;reply text;reason text;facts jsonb;asked jsonb;question text;question_kind text;
 owner_unknown boolean;visit_id uuid;visit_times text;visit_access text;visit_answer uuid;
 attempts integer;context jsonb;attempt_message public.icash_text_messages;
begin
 if not exists(select 1 from public.icash_seller_progress_settings where id=1 and enabled and dialogue_enabled) then return null;end if;
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account and direction='incoming' and state='received';
 if not found or length(m.body)>=1000 then return null;end if;
 select * into t from public.icash_text_threads where id=m.thread_id and account_id=p_account and party='seller';
 if not found then return null;end if;
 source_at:=public.icash_sms_reply_time(m.id);
 if source_at>extract(epoch from now()) or exists(select 1 from public.icash_text_messages newer where newer.account_id=p_account and newer.thread_id=t.id and newer.direction='incoming' and newer.state='received' and (public.icash_sms_reply_time(newer.id),newer.id)>(source_at,m.id)) then return null;end if;
 -- A customer's later message owns the conversation; never answer behind it.
 if exists(select 1 from public.icash_text_messages human where human.account_id=p_account and human.thread_id=t.id and human.direction='outgoing' and human.customer_author_id is not null and human.state in ('accepted','delivered') and human.provider_id is not null and extract(epoch from human.created_at)>source_at) then return null;end if;
 for x in select * from public.icash_text_messages where account_id=p_account and thread_id=t.id and direction='incoming' and state='received' and (public.icash_sms_reply_time(id),id)<=(source_at,m.id) order by public.icash_sms_reply_time(id),id loop
  b:=lower(trim(regexp_replace(replace(x.body,'’',chr(39)),'[[:space:]]+',' ','g')));
  prior_action:=null;prior_anchor:=null;
  select sent.* into prior from public.icash_text_messages sent where sent.account_id=p_account and sent.thread_id=t.id and sent.direction='outgoing' and sent.state='delivered' and sent.provider_id is not null and extract(epoch from sent.created_at)<public.icash_sms_reply_time(x.id) order by sent.created_at desc,sent.id desc limit 1;
  if prior.id is not null then
   select j.analysis->>'dialogueAction',j.analysis->>'dialogueAnchor' into prior_action,prior_anchor from public.icash_text_ai_jobs j where j.account_id=p_account and j.thread_id=t.id and j.outgoing_id=prior.id and j.analysis->>'dialoguePolicy'='seller-dialogue-v1';
  end if;
  -- Explicit prohibitions take precedence over a positive-looking fragment.
  if public.icash_seller_direct_response_match(b,'\m(no (assignments?|wholesalers?|middlem(e|a)n)|direct buyers? only|only (the )?(actual|end|direct) buyer|do not assign|don''t assign|won''t (allow|accept) assignments?)\M') then
   condition_state:='direct_only';condition_id:=x.id;condition_quote:=x.body;condition_answer:=x.id;
  elsif condition_id is not null and b ~ '^(yes[, ]+)?(no (agents?|realtors?|brokers?)[,.]? *(but |and )?)?((an? )?assignments? (is |are |would be )?(fine|okay|ok|acceptable|allowed)( with me)?|i (am|''m) (fine|okay|ok) with (an? )?assignments?)[.! ,]*$' then
   condition_state:='resolved';condition_answer:=x.id;
  elsif public.icash_seller_direct_response_match(b,'\m(no (3rd|third)[ -]part(y|ies))\M') then
   if condition_id is null or condition_state='resolved' then condition_id:=x.id;condition_quote:=x.body;end if;
   condition_state:=case when prior_anchor=condition_id::text and prior_action='explain_assignment' then 'unresolved' when prior_anchor=condition_id::text and prior_action='clarify_buyer_condition' then 'explain_assignment' else 'clarify' end;
   condition_answer:=null;
  elsif b ~ '^(i (just |only )?(mean|meant|want) |just |only )?(no agents?|no realtors?|no brokers?)[.! ,]*$'
    or (condition_id is not null and b ~ '\m(don''t|do not) want (to (use|pay) )?(an? )?(agents?|realtors?|brokers?)\M') then
   if condition_id is null then condition_id:=x.id;condition_quote:=x.body;end if;
   condition_state:='explain_assignment';condition_answer:=x.id;
  elsif condition_id is not null and b ~ '(what.*(assignment|assigning)|what do you mean|how.*assignment)' then
   condition_state:='explain_assignment';condition_answer:=x.id;
  elsif condition_id is not null and b ~ '^(yes[, ]+)?(an? )?(assignment|assigning (the )?(purchase )?contract|another buyer) (is |would be )?(fine|okay|ok|acceptable|allowed)( with me)?[.! ,]*$' then
   condition_state:='resolved';condition_answer:=x.id;
  elsif condition_id is not null and prior_anchor=condition_id::text and prior_action='explain_assignment' then
   if b ~ '^(yes|yeah|yep|sure|ok|okay|that is fine|that''s fine|that works|i would|i would consider that)[.! ,]*$' then condition_state:='resolved';condition_answer:=x.id;
   elsif b ~ '^(no|no i would not|i would not|absolutely not)[.! ,]*$' then condition_state:='direct_only';condition_answer:=x.id;
   elsif x.id=m.id then condition_state:='unresolved';condition_answer:=x.id;end if;
  elsif condition_id is not null and prior_anchor=condition_id::text and prior_action='clarify_buyer_condition' and x.id=m.id then
   -- A bare yes cannot answer an either/or question. Explain the concrete option.
   condition_state:='explain_assignment';condition_answer:=x.id;
  end if;
  if b ~ '\m(visit|showing|view the (house|property)|come (see|look))\M' and b !~ '\m(cancel|withdraw|don''t|do not|no visit)\M' and prior_action is distinct from 'ask_visit_details' then
   if visit_id is null or visit_access is not null then visit_id:=x.id;visit_times:=null;visit_access:=null;visit_answer:=null;end if;
  end if;
  if b ~ '\m(cancel|withdraw|no) (the )?(visit|showing)\M' then visit_id:=null;visit_times:=null;visit_access:=null;end if;
  if prior_anchor=visit_id::text and prior_action='ask_visit_details' and visit_times is null and b ~ '\m(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tomorrow|morning|afternoon|evening|after|before|[0-9]{1,2}(:[0-9]{2})? ?(am|pm))\M' then visit_times:=x.body;visit_answer:=x.id;end if;
  if prior_anchor=visit_id::text and prior_action='ask_visit_access' and visit_access is null then visit_access:=x.body;visit_answer:=x.id;end if;
 end loop;
 b:=lower(trim(regexp_replace(replace(m.body,'’',chr(39)),'[[:space:]]+',' ','g')));
 select coalesce(jsonb_agg(distinct f->>'kind'),'[]') into facts from public.icash_text_ai_jobs j cross join lateral jsonb_array_elements(case when jsonb_typeof(j.analysis->'facts')='array' then j.analysis->'facts' else '[]' end) f
 where j.account_id=p_account and j.thread_id=t.id and exists(select 1 from public.icash_text_messages source where source.account_id=p_account and source.thread_id=t.id and source.direction='incoming' and source.state='received' and public.icash_sms_reply_time(source.id)<=source_at and source.body=f->>'quote');
 select coalesce(jsonb_agg(distinct coalesce(j.analysis->>'dialogueQuestion',j.analysis->>'action')),'[]') into asked from public.icash_text_ai_jobs j where j.account_id=p_account and j.thread_id=t.id and j.outgoing_id is not null and j.message_id<>m.id;
 owner_unknown:=exists(select 1 from public.icash_sms_seller_openings o where o.account_id=p_account and o.thread_id=t.id and o.owner_reply_id is null);
 foreach question_kind in array array['condition','price','timing','owners','occupancy'] loop
  if not facts ? question_kind and not asked ? ('ask_'||question_kind) then
   question:=case question_kind when 'condition' then 'What repairs or updates does the property need?' when 'price' then 'What price did you have in mind?' when 'timing' then 'When would you like to sell?' when 'owners' then 'Are all property owners on board with selling?' when 'occupancy' then 'Is the property vacant, owner occupied, or rented?' end;exit;
  end if;
 end loop;
 if public.icash_seller_response_disposition(m.body) is not null or public.icash_seller_contact_stop(m.body)
  or public.icash_seller_conversation_human(m.body) or b ~ '\m(call me|callback|call back|phone call|ignore (previous|all|the)|system prompt|developer message|wire|bank account|deposit|lawsuit|attorney)\M' then return null;end if;
 if condition_state='direct_only' then reason:='direct_purchase_required';
 elsif condition_state='unresolved' then reason:='buyer_condition_unresolved';
 elsif condition_state='clarify' then
  action:='clarify_buyer_condition';reply:='When you say no third parties, do you mean no agents, or no assigning the purchase contract to another buyer?';
 elsif condition_state='explain_assignment' then
  action:='explain_assignment';reply:='An assignment would let another buyer take over the purchase contract. Would you consider that?';
 elsif public.icash_seller_post_call_identity_reply(p_account,m.id) is not null then
  owner_unknown:=true;action:='clarify_ownership';reply:=public.icash_seller_post_call_identity_reply(p_account,m.id);
 elsif b ~ '^(please |can you |could you )?text me( instead| please)?[.! ]*$'
   and exists(select 1 from public.icash_seller_progress_settings settings where settings.id=1
    and settings.voice_text_enabled_at is not null and m.created_at>=settings.voice_text_enabled_at
    and source_at>=extract(epoch from settings.voice_text_enabled_at))
   and public.icash_seller_voice_text_context(p_account,m.id) then
  owner_unknown:=true;action:='clarify_ownership';
  reply:='Text is fine. Are you the owner of the property we called about?';
 elsif owner_unknown
   and b ~ '^(please |can you |could you )?text me( instead| please)?[.! ]*$|^(sorry[, ]+)?i (can''t|cannot|can not) talk( right now| now)?[.! ]*$'
   and exists(select 1 from public.icash_seller_progress_settings settings where settings.id=1
    and settings.initial_reply_enabled_at is not null
    and m.created_at>=settings.initial_reply_enabled_at
    and source_at>=extract(epoch from settings.initial_reply_enabled_at))
   and exists(select 1 from public.icash_sms_seller_openings opening
    join public.icash_text_messages question_message on question_message.id=opening.owner_question_id
     and question_message.account_id=p_account and question_message.thread_id=t.id
     and question_message.direction='outgoing' and question_message.state='delivered'
     and question_message.provider_id is not null
     and extract(epoch from question_message.created_at)<source_at
    where opening.account_id=p_account and opening.thread_id=t.id and opening.owner_reply_id is null
     and not exists(select 1 from public.icash_text_messages later
      where later.account_id=p_account and later.thread_id=t.id and later.direction='outgoing'
       and later.state in ('accepted','delivered','dispatching')
       and later.id<>question_message.id
       and later.created_at>question_message.created_at and extract(epoch from later.created_at)<source_at)) then
  action:='clarify_ownership';
  reply:=case when b ~ 'text me' then 'Text is fine. Are you the owner of the property we texted about?'
   else 'No problem. Reply here when you are free. Are you the owner of the property we texted about?' end;
 elsif owner_unknown and (b ~ '(how much|what.*offer|what.*pay)' or condition_answer=m.id) then
  action:='clarify_ownership';reply:='An offer depends on the property details. Are you the owner of the property we texted about?';
 elsif visit_id is not null and visit_access is not null then reason:='visit_attendee_required';
 elsif visit_id is not null and visit_times is not null then
  action:='ask_visit_access';reply:='Who will be available to provide access at those times? The visit is not booked.';
 elsif visit_id is not null then
  action:='ask_visit_details';reply:='What days and times work for a property visit? A visit still needs confirmation.';
 elsif b ~ '^(any fees|are there (any )?fees|what (are|about) (the )?fees|do i (have to )?pay (any )?fees|who pays (the )?closing costs)[?! .]*$' then
  action:='explain_fees';reply:='Any fees and closing costs must be agreed in writing before you commit.';
 elsif b ~ '(how (does|would|will) (this|it|the process) work|what( is|''s|s) the process|what happens next|what do you do|how do you (work|buy))' then
  action:='explain_process';reply:='We confirm property details, work out a supported offer, then agree on written terms.';
 elsif b ~ '^(how much( for (it|the (house|property)))?|what( is|''s|s) (the|your) offer|what (can|would|will) you (offer|pay)|can you (give me an offer|make an offer))[?! .]*$' then
  action:='explain_price';reply:='An offer depends on the property details and condition.';
 elsif (jsonb_typeof(m.attachments)='array' and jsonb_array_length(m.attachments)>0) or b ~ '(pictures|photos).*(there|zillow)|go to zillow' then
  action:='continue_details';reply:=case when jsonb_array_length(m.attachments)>0 then 'Thanks, I received the photos.' else 'I can continue without new photos.' end;
 elsif condition_state='resolved' and condition_answer=m.id then action:='continue_details';reply:='Thanks for clarifying.';
 elsif position('?' in b)>0 and length(b)<=300 and b !~ '(\$|[0-9]|offer|price|pay|fees|cost|sign|contract|agreement|accept|deal|closing|legal|title|lien)' then
  action:='clarify_question';reply:='Which part would you like me to clarify?';
 end if;
 if action in ('explain_fees','explain_process','explain_price','continue_details') and question is not null and not owner_unknown then reply:=reply||' '||question;
 else question_kind:=null;end if;
 -- No implication that the seller agreed to assignment from an undelivered question.
 -- An uncertain earlier clarification cannot be retried under a new source ID.
 if action is not null then
  select count(*) into attempts from public.icash_text_ai_jobs j join public.icash_text_messages sent on sent.id=j.outgoing_id and sent.account_id=j.account_id and sent.thread_id=j.thread_id
  where j.account_id=p_account and j.thread_id=t.id and j.message_id<>m.id and j.analysis->>'dialoguePolicy'='seller-dialogue-v1' and j.analysis->>'dialogueAction'=action
   and (case when action in ('clarify_buyer_condition','explain_assignment') then j.analysis->>'dialogueAnchor'=condition_id::text when action in ('ask_visit_details','ask_visit_access') then j.analysis->>'dialogueAnchor'=visit_id::text else sent.created_at>now()-interval '24 hours' end);
  if attempts>=(case when action='clarify_question' then 2 else 1 end) then
   select sent.* into attempt_message from public.icash_text_ai_jobs j join public.icash_text_messages sent on sent.id=j.outgoing_id and sent.account_id=j.account_id and sent.thread_id=j.thread_id
    where j.account_id=p_account and j.thread_id=t.id and j.message_id<>m.id and j.analysis->>'dialoguePolicy'='seller-dialogue-v1' and j.analysis->>'dialogueAction'=action
     and (case when action in ('clarify_buyer_condition','explain_assignment') then j.analysis->>'dialogueAnchor'=condition_id::text when action in ('ask_visit_details','ask_visit_access') then j.analysis->>'dialogueAnchor'=visit_id::text else sent.created_at>now()-interval '24 hours' end)
    order by sent.created_at desc,sent.id desc limit 1;
   reason:=case when attempt_message.state in ('accepted','dispatching') and attempt_message.updated_at>now()-interval '15 minutes' then 'clarification_receipt_pending'
    when attempt_message.state in ('failed','undelivered','rejected') then 'clarification_delivery_failed'
    when attempt_message.state<>'delivered' then 'clarification_receipt_unresolved' else 'clarification_already_attempted' end;
   action:=null;reply:=null;
  end if;
 end if;
 context:=jsonb_build_object('action',action,'reply',reply,'reason',reason,'question',case when question_kind is not null then 'ask_'||question_kind end,
  'anchor',case when action in ('clarify_buyer_condition','explain_assignment') then condition_id when action in ('ask_visit_details','ask_visit_access') then visit_id else m.id end,
  'conditionState',condition_state,'conditionId',condition_id,'conditionQuote',condition_quote,'conditionAnswer',condition_answer,'conditionResolved',condition_state='resolved',
  'visitRequest',visit_id,'visitAvailability',visit_times,'visitAccess',visit_access,'visitAnswer',visit_answer,'ownershipUnconfirmed',owner_unknown,
  'receiptMessageId',attempt_message.id,'sourceBody',m.body,'routineQualification',not owner_unknown and length(m.body)<=500 and b !~ '(\?|\m(offer|accept|agree|sign|contract|assignment|third part|3rd part|fees?|costs?|lien|mortgage|title|lawsuit|visit|showing|call|callback)\M)');
 return context;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_reply_before_viewings(p_account uuid, p_job uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_text_ai_jobs;t public.icash_text_threads;m public.icash_text_messages;ctx jsonb;a text;b text;reply text;kind text;callback_context boolean;photos boolean;complete_time boolean;requested_date date;date_parts text[];photos_seen boolean;photos_asked boolean;call_asked boolean;f jsonb;
begin
 select * into j from public.icash_text_ai_jobs where id=p_job and account_id=p_account;
 if not found or j.state not in ('drafted','queued') then return null;end if;
 select * into t from public.icash_text_threads where id=j.thread_id and account_id=p_account;
 ctx:=public.icash_seller_conversation_context(p_account,t.id);if ctx is null then return null;end if;
 select * into m from public.icash_text_messages where id=j.message_id and thread_id=t.id and account_id=p_account and direction='incoming' and state='received';
 if not found or length(m.body)>=1000 or m.created_at>now() then return null;end if;
 if not exists(select 1 from public.icash_sms_routes where sender=t.sender and recipient=t.recipient and account_id=p_account and not needs_review and revision=m.route_revision) then return null;end if;
 if exists(select 1 from public.icash_text_messages x where x.thread_id=t.id and x.account_id=p_account and x.id<>m.id and x.id is distinct from j.outgoing_id and x.created_at>=m.created_at) then return null;end if;
 b:=lower(trim(m.body));a:=j.analysis->>'action';
 if j.analysis->'humanRequested'='true'::jsonb or j.analysis->'callbackRequested'='true'::jsonb or j.analysis->'optedOut'='true'::jsonb or j.analysis->'declined'='true'::jsonb
  or public.icash_seller_conversation_human(m.body) or public.icash_text_signal(m.body,'seller') in ('declined','withdrawal')
  or b ~ '(\m(stop|unsubscribe|remove me|leave me alone|wrong number|not interested|no thanks)\M|don(''|’)t (call|text|contact)|do not (call|text|contact))'
  or b ~ '\m(ignore (previous|all|the)|system prompt|developer message|wire|bank account|deposit|lawsuit|attorney|sign (the|a)|accept (the|your|my)|agree (to|on))\M' then return null;end if;
 if jsonb_typeof(j.analysis->'facts') is distinct from 'array' or jsonb_array_length(j.analysis->'facts')>8 then return null;end if;
 for f in select value from jsonb_array_elements(j.analysis->'facts') loop
  if f->>'kind' not in ('condition','price','timing','owners','occupancy','callback','photos') or f->>'kind' is null
   or length(coalesce(f->>'quote','')) not between 1 and 500
   or not exists(select 1 from public.icash_text_messages source where source.account_id=p_account and source.thread_id=t.id and source.direction='incoming' and source.state='received' and source.created_at<=m.created_at and source.body=f->>'quote') then return null;end if;
 end loop;
 photos:=jsonb_typeof(m.attachments)='array' and jsonb_array_length(m.attachments)>0;
 photos_seen:=exists(select 1 from public.icash_text_messages source where source.thread_id=t.id and source.account_id=p_account and source.direction='incoming' and source.state='received' and source.created_at<=m.created_at and jsonb_typeof(source.attachments)='array' and jsonb_array_length(source.attachments)>0);
 photos_asked:=exists(select 1 from public.icash_text_ai_jobs prior where prior.account_id=p_account and prior.thread_id=t.id and prior.id<>j.id and prior.outgoing_id is not null and (prior.analysis->>'action'='ask_photos' or prior.analysis->>'conversationNextQuestion'='photos'));
 call_asked:=exists(select 1 from public.icash_text_ai_jobs prior where prior.account_id=p_account and prior.thread_id=t.id and prior.id<>j.id and prior.outgoing_id is not null and (prior.analysis->>'action' in ('ask_callback','ask_callback_details') or prior.analysis->>'conversationNextQuestion'='callback'));

 callback_context:=public.icash_text_signal(m.body,'seller')='callback' or b ~ '\m(missed (your|the) call|couldn(''|’)t answer|could not answer|sorry i missed (it|you))\M'
  or exists(select 1 from public.icash_text_ai_jobs prior join public.icash_text_messages sent on sent.id=prior.outgoing_id and sent.account_id=prior.account_id and sent.thread_id=prior.thread_id
   where prior.account_id=p_account and prior.thread_id=t.id and prior.id<>j.id and (prior.analysis->>'action' in ('ask_callback','ask_callback_details') or prior.analysis->>'conversationNextQuestion'='callback')
   and sent.state in ('accepted','delivered') and sent.provider_id is not null and sent.created_at<m.created_at)
  or exists(select 1 from public.icash_text_messages sent where sent.thread_id=t.id and sent.account_id=p_account and sent.direction='outgoing' and sent.state in ('accepted','delivered') and sent.provider_id is not null and sent.created_at<m.created_at
    and sent.body in ('When is a good time to talk about a cash offer?','What date, time, and time zone work for a callback?'));
 if a='call_unavailable' then
  return public.icash_seller_sms_call_failure_reply(p_account,m.id);
 elsif a='call_now' then
  if not public.icash_seller_sms_call_current(p_account,m.id) or not exists(
   select 1 from public.icash_voice_jobs v join public.icash_call_recordings r on r.voice_job_id=v.id and r.account_id=v.account_id
   where v.account_id=p_account and v.sms_source_message_id=m.id and r.call_sid is not null and r.call_ended_at is null) then return null;end if;
  return 'Calling you now.';
 elsif a='reply_identity' then
  if not public.icash_seller_identity_question(m.body) and b !~ '(who (is|are)|who''s|whos|what company|what business|how did you get|where did you get|why (are you|did you)|are you (a |an )?(human|real person|bot|ai|robot)|is this (a |an )?(human|real person|bot|ai|robot))' then return null;end if;
  if b ~ '(are you|is this).*(human|real person|bot|ai|robot|automated)' then
   reply:='I am '||(ctx->>'assistantName')||', the AI assistant for '||(ctx->>'principal')||'. I can help with your property inquiry.';
  elsif exists(select 1 from public.icash_text_messages sent where sent.account_id=p_account and sent.thread_id=t.id and sent.direction='outgoing' and sent.state in ('accepted','delivered') and sent.provider_id is not null and sent.created_at<m.created_at and (sent.body ilike '%AI assistant%' or sent.body ilike '%AI for %') and position(ctx->>'principal' in sent.body)>0) then
   reply:='I am '||(ctx->>'assistantName')||', reaching out for '||(ctx->>'principal')||' about a possible cash offer. Your inquiry came through HomeOffer Network.';
  else
   reply:='I am '||(ctx->>'assistantName')||', the AI assistant for '||(ctx->>'principal')||'. Your property inquiry came through HomeOffer Network.';
  end if;
 elsif a='explain_process' then
  if b !~ '(how (does|would|will) (this|it|the process) work|what( is|[''’]s|s) the process|what happens next|what do you do|how do you (work|buy))' then return null;end if;
  if not call_asked then reply:='I gather property details for review of a possible cash offer. When is a good time to talk?';
  else reply:='I gather property details for review of a possible cash offer. Any offer would need separate review and agreement.';end if;
 elsif a='explain_price' then
  if b !~ '(how much|what( is|[''’]s|s) (the|your) offer|what (can|would|will) you (offer|pay)|can you (give|offer|pay))' then return null;end if;
  if not exists(select 1 from jsonb_array_elements(j.analysis->'facts') x where x->>'kind'='price') then
   reply:='A possible cash offer needs a property review first. What price did you have in mind?';
  else reply:='A possible cash offer needs a property review first. An asking price alone is not an agreed offer.';end if;
 elsif a='photo_received' then
  if not coalesce(photos,false) then return null;end if;
  if not call_asked and not exists(select 1 from jsonb_array_elements(j.analysis->'facts') x where x->>'kind'='callback') then
   reply:='Thanks for sending those for review. When is a good time to talk about a possible cash offer?';
  else reply:='Thanks for sending those. They still need review.';end if;
 elsif a='ask_callback_details' or a='acknowledge_callback' then
  if not coalesce(callback_context,false) or b ~ '\m(don(''|’)t|do not|never|cancel|stop)\M' then return null;end if;
  -- Require an explicit year and a real calendar date. Relative or invalid
  -- dates stay a clarification; we never normalize them into a booking.
  requested_date:=null;
  begin
   requested_date:=substring(b from '\m([0-9]{4}-[0-9]{2}-[0-9]{2})\M')::date;
   if requested_date is null then
    date_parts:=regexp_match(b,'\m(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?) ([0-9]{1,2}),? ([0-9]{4})\M');
    if date_parts is not null then
     requested_date:=make_date(date_parts[3]::integer,array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'],left(date_parts[1],3)),date_parts[2]::integer);
    end if;
   end if;
  exception when datetime_field_overflow or invalid_datetime_format then requested_date:=null;
  end;
  complete_time:=requested_date is not null and requested_date>=current_date
   and b ~ '\m(1[0-2]|[1-9])(:[0-5][0-9])? ?(am|pm)\M'
   and b ~ '\m(est|edt|cst|cdt|mst|mdt|pst|pdt|et|ct|mt|pt|utc|eastern|central|mountain|pacific)\M'
   and exists(select 1 from jsonb_array_elements(j.analysis->'facts') x where x->>'kind'='callback' and x->>'quote'=m.body);
  if a='acknowledge_callback' and coalesce(complete_time,false) then
   if not photos_seen and not photos_asked then
    reply:='That call time still needs confirmation. Could you text a few recent photos of the property?';
   else reply:='Thanks for sharing your requested call time. It still needs confirmation and no call is booked yet.';end if;
  else
   if b ~ '\m(tomorrow|today|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\M' and b !~ '\m[0-9]{1,2}(:[0-9]{2})? ?(am|pm)\M' then reply:='What time works for you?';
   elsif b ~ '\m[0-9]{1,2}(:[0-9]{2})? ?(am|pm)\M' and b !~ '\m(today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday|[0-9]{4}-[0-9]{2}-[0-9]{2})\M' then reply:='Does that time work today or tomorrow?';
   elsif b ~ '\m[0-9]{1,2}(:[0-9]{2})? ?(am|pm)\M' then reply:='What time zone are you in?';
   else reply:='Are you free for a quick call now, or would later work better?';end if;
  end if;
 elsif a='ask_callback' then
  if call_asked or exists(select 1 from jsonb_array_elements(j.analysis->'facts') x where x->>'kind'='callback') then return null;end if;
  reply:='When is a good time to talk about a possible cash offer?';
 elsif a='ask_photos' then
  if photos_seen or photos_asked then return null;end if;
  reply:='Could you text a few recent photos of the property, including any areas that need repairs?';
 else
  kind:=case a when 'ask_condition' then 'condition' when 'ask_price' then 'price' when 'ask_timing' then 'timing' when 'ask_owners' then 'owners' when 'ask_occupancy' then 'occupancy' end;
  if kind is null then return null;end if;
  if exists(select 1 from jsonb_array_elements(j.analysis->'facts') x where x->>'kind'=kind) then return null;end if;
  reply:=case a when 'ask_condition' then 'Thanks for the details. What repairs or updates does the property need?'
   when 'ask_price' then 'What price did you have in mind?'
   when 'ask_timing' then 'When would you ideally like to sell?'
   when 'ask_owners' then 'Are all property owners on board with selling?'
   when 'ask_occupancy' then 'Is the property vacant, owner occupied, or rented?' end;
 end if;
 -- Mixed unanswered questions/negotiation cannot be silently turned into prompts.
 if a not in ('reply_identity','explain_process','explain_price','ask_callback_details','acknowledge_callback')
  and (position('?' in b)>0 or public.icash_text_signal(m.body,'seller')='callback') then return null;end if;
 -- One question/intent per thread; identity and clarifying dates may be repeated
 -- once when explicitly asked again. A provider-uncertain prior never invites retry.
 if (select count(*) from public.icash_text_ai_jobs prior where prior.thread_id=t.id and prior.account_id=p_account and prior.id<>j.id and prior.outgoing_id is not null and prior.analysis->>'action'=a)>=(case when a in ('reply_identity','ask_callback_details') then 2 else 1 end) then return null;end if;
 -- Preserve the existing one-segment ASCII policy, including its exact alphabet.
 if length(reply)>160 or (reply ~ '[^A-Za-z0-9 .,!?]' and length(reply)>35) then return null;end if;
 return reply;
end $function$
